function validate([queries, k]) {
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 200000) return 'queries needs 1 to 2 * 10^5 points.';
  const seen = new Set();
  for (const point of queries) {
    if (!Array.isArray(point) || point.length !== 2 || !point.every(v => Number.isInteger(v) && Math.abs(v) <= 1000000000)) return 'Each query is [x, y] with -10^9 <= x, y <= 10^9.';
    if (seen.has(point[0] + ',' + point[1])) return 'Each point gets at most one obstacle.';
    seen.add(point[0] + ',' + point[1]);
  }
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is between 1 and 10^5.';
  return null;
}

