  const heap = [];
  const swap = (i, j) => {
    [heap[i], heap[j]] = [heap[j], heap[i]];
  };
  const siftUp = (child) => {
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent] >= heap[child]) return;
      swap(parent, child);
      child = parent;
    }
  };
  const siftDown = (parent) => {
    while (true) {
      const left = 2 * parent + 1;
      const right = left + 1;
      let largest = parent;
      if (left < heap.length && heap[left] > heap[largest]) largest = left;
      if (right < heap.length && heap[right] > heap[largest]) largest = right;
      if (largest === parent) return;
      swap(parent, largest);
      parent = largest;
    }
  };
  const results = [];
  for (const [x, y] of queries) {
    const distance = Math.abs(x) + Math.abs(y);
    if (heap.length < k) {
      heap.push(distance);
      siftUp(heap.length - 1);
    } else if (distance < heap[0]) {
      heap[0] = distance;
      siftDown(0);
    }
    results.push(heap.length === k ? heap[0] : -1);
  }
  return results;
}

