function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const q = large ? 2000 : int(1, 10);
  // Points come from a small box around the origin (many equal distances) or from the whole range.
  const reach = large ? (rand() < 0.5 ? 40 : 1000000000) : (rand() < 0.8 ? 4 : 1000000000);
  const seen = new Set();
  const queries = [];
  while (queries.length < q) {
    const x = int(-reach, reach);
    const y = int(-reach, reach);
    if (seen.has(x + ',' + y)) continue;
    seen.add(x + ',' + y);
    queries.push([x, y]);
  }
  const k = large ? (rand() < 0.5 ? int(1, 50) : int(51, 1500)) : int(1, 7);
  return [queries, k];
}
